// Pure data + helpers shared between client and server i18n.
// Split out of i18n.tsx because that file uses "use client", which makes
// non-component exports (like the translations dictionary) become opaque
// "client reference" stubs when imported from a server component — leading
// to "Cannot read properties of undefined (reading <key>)" in tServer().
//
// Server code (i18n-server.ts) imports here directly. Client code keeps
// importing from "@/lib/i18n", which re-exports these names.

import { LIVE_MODULES, MODULE_NODES } from "@/data/pitchFacts";

export type Lang = "en" | "ru" | "kk" | "de" | "fr" | "es" | "zh" | "ja" | "ar" | "pt" | "tr";

export const LANGS: Lang[] = ["ru", "en", "kk", "de", "fr", "es", "zh", "ja", "ar", "pt", "tr"];

export const LANG_FLAG: Record<Lang, string> = {
  en: "🇺🇸", ru: "🇷🇺", kk: "🇰🇿", de: "🇩🇪", fr: "🇫🇷",
  es: "🇪🇸", zh: "🇨🇳", ja: "🇯🇵", ar: "🇸🇦", pt: "🇧🇷", tr: "🇹🇷",
};

