    /* Academy \u2014 page-level */
    "constitution.learn.title": "AEVION Constitution Academy",
    "constitution.learn.subtitle": "8 \u0443\u0440\u043e\u043a\u043e\u0432, \u043f\u043e \u043e\u0434\u043d\u043e\u043c\u0443 \u043d\u0430 \u043a\u0430\u0436\u0434\u044b\u0439 \u043f\u043e\u043b\u0437\u0443\u043d\u043e\u043a. \u0422\u0435\u043e\u0440\u0438\u044f + \u0438\u0441\u0442\u043e\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043f\u0440\u0438\u043c\u0435\u0440 + \u043f\u0440\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0437\u0430\u0434\u0430\u043d\u0438\u0435. \u041f\u043e\u0441\u043b\u0435 8/8 \u2014 \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442 \u0432 PDF.",
    "constitution.learn.progress": "\u041f\u0440\u043e\u0433\u0440\u0435\u0441\u0441",
    "constitution.learn.cert": "\u0421\u043a\u0430\u0447\u0430\u0442\u044c \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442",
    "constitution.learn.reset": "\u0421\u0431\u0440\u043e\u0441\u0438\u0442\u044c \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0441",
    "constitution.learn.theory_heading": "\u0422\u0435\u043e\u0440\u0438\u044f",
    "constitution.learn.example_heading": "\u0418\u0441\u0442\u043e\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043f\u0440\u0438\u043c\u0435\u0440",
    "constitution.learn.task_heading": "\ud83c\udfaf \u0417\u0430\u0434\u0430\u043d\u0438\u0435",
