  "explore.disclaimer": "\u041a\u0430\u0440\u0442\u043e\u0447\u043a\u0438 \u0441 \u043f\u043e\u043c\u0435\u0442\u043a\u043e\u0439 DEMO \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442 \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435, \u0447\u0442\u043e\u0431\u044b \u043c\u043e\u0436\u043d\u043e \u0431\u044b\u043b\u043e \u043f\u043e\u0441\u043c\u043e\u0442\u0440\u0435\u0442\u044c \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0443 \u0431\u0435\u0437 \u0441\u0438\u0434\u0438\u043d\u0433\u0430 \u043a\u043e\u0448\u0435\u043b\u044c\u043a\u0430.",
  "explore.badge.demo": "\u0414\u0435\u043c\u043e",
  "explore.group.story": "\u0418\u0441\u0442\u043e\u0440\u0438\u044f",
