  // budgetPage /bank/budget
  "budgetPage.kicker": "\u041c\u0435\u0441\u044f\u0447\u043d\u044b\u0439 \u0431\u044e\u0434\u0436\u0435\u0442",
  "budgetPage.headline": "\u041b\u0438\u043c\u0438\u0442\u044b \u0441 \u043f\u0443\u043b\u044c\u0441\u043e\u043c.",
  "budgetPage.lede": "\u0423\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0435 \u043b\u0438\u043c\u0438\u0442 \u043d\u0430 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044e. \u0422\u0435\u043c\u043f \u0432 \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u043c \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u043f\u0440\u043e\u0442\u0438\u0432 \u0434\u043d\u044f \u043c\u0435\u0441\u044f\u0446\u0430 \u2014 \u0438 \u043f\u0440\u043e\u0433\u043d\u043e\u0437 \u043d\u0430 \u043a\u043e\u043d\u0435\u0446 \u043c\u0435\u0441\u044f\u0446\u0430, \u043f\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043c \u043b\u0438\u043c\u0438\u0442 \u0431\u0443\u0434\u0435\u0442 \u043f\u0440\u043e\u0431\u0438\u0442.",
  "budgetPage.stat.spent": "\u041f\u043e\u0442\u0440\u0430\u0447\u0435\u043d\u043e",
  "budgetPage.stat.spent.hint": "\u0414\u0435\u043d\u044c {day} \u0438\u0437 {days}",
