  "budgetPage.stat.cap.hint": "\u0421\u0443\u043c\u043c\u0430 \u043b\u0438\u043c\u0438\u0442\u043e\u0432 \u043f\u043e \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044f\u043c",
  "budgetPage.stat.cap.empty": "\u041b\u0438\u043c\u0438\u0442\u044b \u0435\u0449\u0451 \u043d\u0435 \u0437\u0430\u0434\u0430\u043d\u044b",
