  "insightsPage.bar.aria": "\u0421\u0442\u044d\u043a\u043e\u0432\u0430\u044f \u043f\u043e\u043b\u043e\u0441\u0430 \u0442\u0440\u0430\u0442 \u043f\u043e \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044f\u043c",
