  "recurringPage.kicker": "\u0410\u0432\u0442\u043e\u043f\u0438\u043b\u043e\u0442",
  "recurringPage.headline": "\u0422\u04b1\u0440\u0430\u049b\u0442\u044b \u0442\u04e9\u043b\u0435\u043c\u0434\u0435\u0440.",
  "recurringPage.lede": "\u0410\u0432\u0442\u043e\u043c\u0430\u0442\u0442\u044b \u0436\u04b1\u043c\u044b\u0441 \u0456\u0441\u0442\u0435\u0439\u0442\u0456\u043d \u0430\u0443\u0434\u0430\u0440\u044b\u043c\u0434\u0430\u0440\u0434\u044b \u043e\u0440\u043d\u0430\u0442\u044b\u04a3\u044b\u0437: \u0436\u0430\u0437\u044b\u043b\u044b\u043c\u0434\u0430\u0440, \u0436\u0430\u043b\u0430\u049b\u044b, \u0436\u0430\u043b\u0434\u0430\u0443 \u0430\u049b\u044b\u0441\u044b. Backend-\u043a\u0435 \u0436\u04af\u0433\u0456\u043d\u0431\u0435\u0439 \u0442\u043e\u049b\u0442\u0430\u0442\u044b\u04a3\u044b\u0437 \u043d\u0435\u043c\u0435\u0441\u0435 \u0436\u043e\u0439\u044b\u04a3\u044b\u0437.",
