  "budgetPage.kicker": "\u0410\u0439\u043b\u044b\u049b \u0431\u044e\u0434\u0436\u0435\u0442",
  "budgetPage.headline": "\u041b\u0438\u043c\u0438\u0442\u0442\u0435\u0440 \u0442\u0456\u0440\u0456.",
  "budgetPage.lede": "\u0421\u0430\u043d\u0430\u0442 \u0431\u043e\u0439\u044b\u043d\u0448\u0430 \u043b\u0438\u043c\u0438\u0442 \u049b\u043e\u0439\u044b\u04a3\u044b\u0437. \u0410\u0439\u0434\u044b\u04a3 \u043a\u04af\u043d\u0456\u043c\u0435\u043d \u0441\u0430\u043b\u044b\u0441\u0442\u044b\u0440\u044b\u043b\u0493\u0430\u043d \u043d\u0430\u049b\u0442\u044b \u0443\u0430\u049b\u044b\u0442\u0442\u0430\u0493\u044b \u049b\u0430\u0440\u049b\u044b\u043d \u2014 \u0436\u04d9\u043d\u0435 \u043b\u0438\u043c\u0438\u0442 \u0430\u0441\u044b\u0440\u044b\u043b\u043c\u0430\u0441 \u0431\u04b1\u0440\u044b\u043d\u0493\u044b \u0430\u0439 \u0441\u043e\u04a3\u044b\u043d\u0430 \u0431\u043e\u043b\u0436\u0430\u043c.",
