  "budgetPage.stat.cap.hint": "\u0421\u0430\u043d\u0430\u0442\u0442\u0430\u0440 \u043b\u0438\u043c\u0438\u0442\u0442\u0435\u0440\u0456\u043d\u0456\u04a3 \u049b\u043e\u0441\u044b\u043d\u0434\u044b\u0441\u044b",
