export function interpolate(s: string, vars?: Record<string, string | number>): string {
  if (!vars) return s;
  let r = s;
  for (const [k, v] of Object.entries(vars)) {
    r = r.split(`{${k}}`).join(String(v));
  }
  return r;
}
